examples.code:
MonarchCelebration(
    title = "Workspace verified",
    message = "Your public profile now shows the verified badge.",
    icon = { MonarchIcon(SampleIcons.Success, contentDescription = null) },
) {
    MonarchButton(text = "Continue", onClick = {}, variant = MonarchButtonVariant.Primary)
}

if (verified) {
    // The celebration brings its own heading, so the dialog has no title; TalkBack names it by its pane title.
    MonarchDialog(
        onDismissRequest = { verified = false },
        title = null,
        paneTitle = "Domain verified",
        content = {
            MonarchCelebration(
                title = "Domain verified",
                message = "Email from acme.com is now signed.",
            ) {
                MonarchButton(
                    text = "Continue",
                    onClick = { verified = false },
                    variant = MonarchButtonVariant.Primary,
                )
            }
        },
    )
}
